import{_ as s,o as a,c as t,a5 as e}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"语法高亮器","description":"","frontmatter":{"title":"语法高亮器","order":5},"headers":[],"relativePath":"zh/2.4/tutorial/core/ks-editor-highlighter.md","filePath":"zh/2.4/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),h={name:"zh/2.4/tutorial/core/ks-editor-highlighter.md"};function l(n,i,p,r,d,o){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="knd-kshighlighter-编辑器语法高亮" tabindex="-1">KND_KsHighlighter 编辑器语法高亮 <a class="header-anchor" href="#knd-kshighlighter-编辑器语法高亮" aria-label="Permalink to &quot;KND_KsHighlighter 编辑器语法高亮&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>语法高亮是编辑器的重要组成部分，它能帮助开发者直观地识别代码结构，从而提升编写效率和可读性。<br><code>KND_KsHighlighter</code> 是基于 Godot 引擎的 <code>SyntaxHighlighter</code> 实现的一款高亮器，专门用于 KS 脚本。它将高亮规则集中定义在单个脚本中，使得自定义和扩展变得非常灵活——你可以轻松调整现有规则，也可以添加全新的配色方案。</p><h2 id="基本实现" tabindex="-1">基本实现 <a class="header-anchor" href="#基本实现" aria-label="Permalink to &quot;基本实现&quot;">​</a></h2><p>在 <code>KND_KsHighlighter</code> 中，高亮规则存储为一个数组，每个数组元素都是一个字典，包含两个键：</p><ul><li><code>regex</code>：用于匹配文本的正则表达式（Godot 的 RegEx 语法）。</li><li><code>color</code>：匹配文本的颜色，使用 <code>Color(r, g, b, a)</code> 表示，其中 <code>a</code> 为透明度（可选，默认为 1.0）。</li></ul><p>示例结构如下：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;regex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b(if|else|endif)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>高亮器会按数组顺序依次匹配，后应用的规则可能覆盖先前的匹配，因此规则的顺序至关重要（建议将通用命令放在前面，字符串和注释放在后面，以保证覆盖效果合理）。</p><h2 id="自定义配色方案" tabindex="-1">自定义配色方案 <a class="header-anchor" href="#自定义配色方案" aria-label="Permalink to &quot;自定义配色方案&quot;">​</a></h2><p>你可以通过两种方式为编辑器应用自定义高亮：</p><h3 id="方式一-修改资源文件-推荐" tabindex="-1">方式一：修改资源文件（推荐） <a class="header-anchor" href="#方式一-修改资源文件-推荐" aria-label="Permalink to &quot;方式一：修改资源文件（推荐）&quot;">​</a></h3><p>默认的配色方案以资源文件形式存储在：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres</span></span></code></pre></div><p>直接编辑该资源文件可以保留修改，并避免每次重新生成。<br> 在代码中加载并使用该资源：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><h3 id="方式二-动态创建实例" tabindex="-1">方式二：动态创建实例 <a class="header-anchor" href="#方式二-动态创建实例" aria-label="Permalink to &quot;方式二：动态创建实例&quot;">​</a></h3><p>你也可以在代码中直接创建一个新的 <code>KND_KsHighlighter</code> 实例，并为其设置自定义规则（例如通过修改脚本中的 <code>highlight_rules</code>）：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KND_KsHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><blockquote><p><strong>注意</strong>：如果直接修改了 <code>KND_KsHighlighter.gd</code> 脚本，可能需要重新生成资源文件才能使更改生效。推荐优先使用资源文件方式，以便更清晰地管理配色。</p></blockquote>`,20)])])}const c=s(h,[["render",l]]);export{g as __pageData,c as default};
